html:
{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead, footer, print_settings=None, print_heading_template=None) -%}
	{% if letter_head and not no_letterhead %}
		<div class="letter-head" style="margin-bottom: 0px !important;">{{ letter_head }}</div>
	{% endif %}
{%- endmacro -%}

{% for page in layout %}
<div class="page-break invoice-wrapper">
	<div {% if print_settings.repeat_header_footer %} id="header-html" class="hidden-pdf" {% endif %}>
		{{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}
	</div>

	<style>
		.invoice-wrapper {
			font-family: "Arial", sans-serif;
			color: #000;
			font-size: 12px;
		}
		.print-format-body {
			padding: 0px !important;
			margin-top: 5px !important;
		}
		.text-center { text-align: center; }
		.text-left { text-align: left; }
		.text-right { text-align: right; }
		.text-bold { font-weight: bold; }

		.info-table {
			width: 100%;
			margin-bottom: 8px; 
			border-collapse: collapse;
		}
		.info-table td {
			vertical-align: top;
			line-height: 1.2; 
			padding: 0px !important;
		}

		.right-info-table {
			width: 100%;
			border-collapse: collapse;
		}
		.right-info-table td {
			padding: 0px !important;
			line-height: 1.2;
		}

		table.items-table {
			width: 100%;
			border-collapse: collapse;
			margin-bottom: 8px;
			border: 1px solid #000;
			table-layout: fixed;
		}

		table.items-table th, 
		table.items-table td {
			border: 1px solid #000;
			padding: 1px 4px !important; 
			min-height: 6mm;
			line-height: 1.1 !important;
			vertical-align: middle !important;
			word-wrap: break-word;
			overflow-wrap: break-word;
			word-break: break-word;
		}
		table.items-table th {
			background-color: #f0f0f0;
			text-align: center;
			font-weight: bold;
		}

		table.items-table tr.filler-row td {
			border-top: none;
			border-bottom: none;
			border-left: 1px solid #000;
			border-right: 1px solid #000;
		}

		.totals-row td, .amount-words-row td {
			border: 2px solid #000;
			padding: 2px 10px !important; 
			min-height: 6mm;
			line-height: 1.1 !important;
			vertical-align: middle !important;
			word-wrap: break-word;
			overflow-wrap: break-word;
			word-break: break-word;
		}

		.signature-section {
			width: 100%;
			margin-top: 15px; 
			margin-bottom: 0px !important; /* Reduced to avoid extra blank pages */
			border-collapse: collapse;
			page-break-inside: avoid; /* Prevents awkward page splits */
		}
		.signature-section td {
			width: 33%;
			vertical-align: bottom;
			text-align: center;
		}

		.terms-section {
			font-size: 11px;
			line-height: 1.4;
			margin-top: 15px;
			page-break-inside: avoid;
		}

        .letter-head-footer {
            margin-top: 5px;
        }
	</style>

	<div class="print-format-body">

		<table class="info-table">
			<tr>
				<td style="width: 55%; padding-right: 10px !important;">
					<strong>To,</strong><br>
					<strong>{{ doc.customer_name or doc.party_name }}</strong><br>
					{% if doc.customer_address %}
						{% set customer_address = frappe.db.get_value("Address", doc.customer_address, ["address_line1", "address_line2", "city", "state", "pincode", "country"], as_dict=True) %}
						{% if customer_address.address_line1 %}{{ customer_address.address_line1 }}<br>{% endif %}
						{% if customer_address.address_line2 %}{{ customer_address.address_line2 }}<br>{% endif %}
						{% if customer_address.city or customer_address.country %}{{ customer_address.city or "" }}{% if customer_address.city and customer_address.country %}, {% endif %}{{ customer_address.country or "" }}<br>{% endif %}
					{% endif %}

                    {% set customer_trn = frappe.db.get_value("Customer", doc.party_name, "tax_id") if doc.quotation_to == "Customer" else None %}{% if customer_trn %}<strong>TRN:</strong> {{ customer_trn }}<br>{% endif %}
					{% if doc.project %}<strong>Project :</strong> {{ doc.project }}<br>{% endif %}
					{% if doc.cc_attention_to or doc.contact_display %}<strong>Attn:</strong> {{ doc.cc_attention_to or doc.contact_display }}{% endif %}
				</td>
				<td style="width: 45%;">
					<table class="right-info-table">
						<tr><td style="width: 40%;"><strong>Quote No</strong></td><td>: <strong>{{ doc.name }}</strong></td></tr>
						<tr><td><strong>Date</strong></td><td>: {{ frappe.utils.format_date(doc.transaction_date) }}</td></tr>
						<tr><td><strong>Payment Terms</strong></td><td>: {{ doc.payment_terms_template or doc.cen_payment_terms or "" }}</td></tr>
					</table>
				</td>
			</tr>
		</table>

		<!-- Items Table -->
		{% set show_item_code = not doc.cc_hide_item_code %}
		{% set col_count = 7 if show_item_code else 6 %}
		<table class="items-table">
			<thead>
				<tr>
					<th style="width: 5%;">Sl No.</th>
					{% if show_item_code %}<th style="width: 10%;">Item Code</th>{% endif %}
					<th style="width: {% if show_item_code %}45{% else %}55{% endif %}%; text-align: left;">DESCRIPTION</th>
					<th style="width: 7%;">QTY</th>
					<th style="width: 8%;">Unit</th>
					<th style="width: 12%;">RATE</th>
					<th style="width: 13%;">AMOUNT</th>
				</tr>
			</thead>
			<tbody>
				{% for item in doc.items %}
				<tr>
					<td class="text-center">{{ loop.index }}</td>
                    {% if show_item_code %}<td class="text-center">{{ item.item_code }}</td>{% endif %}
                    <td>{{ item.description }}</td>					
                    <td class="text-center">{{ item.get_formatted("qty", 0) }}</td>
					<td class="text-center">{{ item.uom }}</td>
					<td class="text-right">{{ frappe.utils.fmt_money(item.rate, precision=2, currency="") }}</td>
					<td class="text-right">{{ frappe.utils.fmt_money(item.amount, precision=2, currency="") }}</td>
				</tr>
				{% endfor %}
				{% set min_rows = 15 %}
				{% for i in range(min_rows - (doc.items|length)) %}
				<tr class="filler-row">
					<td>&nbsp;</td>
					{% if show_item_code %}<td>&nbsp;</td>{% endif %}
					<td>&nbsp;</td>
					<td>&nbsp;</td>
					<td>&nbsp;</td>
					<td>&nbsp;</td>
					<td>&nbsp;</td>
				</tr>
				{% endfor %}

				<tr class="totals-row">
					<td colspan="{{ col_count - 1 }}" class="text-right">TOTAL</td>
					<td class="text-right text-bold">{{ frappe.utils.fmt_money(doc.total, precision=2, currency="") }}</td>
				</tr>

				<tr class="totals-row">
					<td colspan="{{ col_count - 1 }}" class="text-right">Discount</td>
					<td class="text-right">{% if doc.discount_amount %}{{ frappe.utils.fmt_money(doc.discount_amount, precision=2, currency="") }}{% endif %}</td>
				</tr>

				{%- for tax in doc.taxes -%}
				<tr class="totals-row">
					<td colspan="{{ col_count - 1 }}" class="text-right">{{ tax.description }}</td>
					<td class="text-right text-bold">{{ frappe.utils.fmt_money(tax.tax_amount, precision=2, currency="") }}</td>
				</tr>
				{%- endfor -%}

				<tr class="totals-row">
					<td colspan="{{ col_count - 1 }}" class="text-right">NET AMOUNT</td>
					<td class="text-right text-bold">{{ frappe.utils.fmt_money(doc.grand_total, precision=2, currency="") }}</td>
				</tr>

                <tr class="amount-words-row">
                    <td colspan="{{ col_count }}" class="text-left">
                        Amount In Words: <strong>{{ doc.in_words }}</strong>
                    </td>
                </tr>
			</tbody>
		</table>

		<!-- Dynamic Signatures -->
		<table class="signature-section">
			<tr>
				<td>
					<strong>Declaration:</strong><br><br><br>
					_________________________<br>
					Customer's Seal and Signature
				</td>
				<td>
					<!-- Stamp Space -->
				</td>
				<td>
					<strong>For {{ doc.company }}</strong><br><br><br>
					_________________________<br>
					Authorised Signature
				</td>
			</tr>
		</table>

		<!-- Terms and Conditions Section -->
		{% if doc.terms %}
		<div class="terms-section">
			<strong>TERMS AND CONDITIONS:</strong><br>
			{{ doc.terms }}
		</div>
		{% endif %}

	</div>

    <div id="footer-html" class="visible-pdf">
        {% if not no_letterhead and footer %}
            <div class="letter-head-footer">
                {{ footer }}
            </div>
        {% endif %}
    </div>

</div>
{% endfor %}
